// TestQA_Acceptance is the independent e2e for AC-1/AC-4/AC-6 + re-scan
// idempotency. It builds the REAL mellifera server + base-scanner binaries,
// starts the server on a temp SQLite DB, drives the three HTTP endpoints with a
// real client, and scans a fixture tree the REAL base-scanner subprocess walks
// + ffprobes. Expected parse values are independently derived below (qaExpected).
func TestQA_Acceptance(t *testing.T) {
	if testing.Short() {
		t.Skip("QA acceptance e2e: skips under -short (builds binaries + subprocess)")
	}
	if _, err := exec.LookPath("ffprobe"); err != nil {
		t.Skip("ffprobe not on PATH — skipping QA-1 e2e (INV4)")
	}
	if _, err := exec.LookPath("ffmpeg"); err != nil {
		t.Skip("ffmpeg not on PATH — cannot generate QA-1 media fixtures")
	}

	tmp := t.TempDir()
	serverBin := qaBuildBinary(t, tmp, "qa-mellifera-server", "./cmd/mellifera")
	scannerBin := qaBuildBinary(t, tmp, "qa-base-scanner", "./plugins/base-scanner")
	tvParserBin := qaBuildBinary(t, tmp, "qa-tv-parser", "./plugins/tv-parser")
	fixtureRoot := qaWriteFixtures(t)
	token := "qa-acceptance-token"
	baseURL := qaStartServer(t, serverBin, scannerBin, tvParserBin, tmp, token)
	client := &http.Client{Timeout: 60 * time.Second}

	libID := qaCreateLibrary(t, client, baseURL, token, fixtureRoot)
	first := qaScanLibrary(t, client, baseURL, token, libID)

	// Independently derived counts: 3 ffmpeg-generated media + 1 zero-byte
	// corrupt.mkv are regular .mkv files under root => discovered/persisted 4.
	// The escape symlink is not a regular file, so WalkDir never emits it.
	if first.Discovered != 4 {
		t.Fatalf("QA AC-1: discovered = %d, want 4 (3 media + corrupt.mkv; escape symlink not regular)", first.Discovered)
	}
	if first.Persisted != 4 {
		t.Fatalf("QA AC-1: persisted = %d, want 4", first.Persisted)
	}
	if !qaWarnsAbout(first.Warnings, "ffprobe") {
		t.Fatalf("QA AC-6: scan warnings = %v, want >=1 ffprobe soft-fail entry", first.Warnings)
	}

	byRel := qaIndexByPath(t, qaListItems(t, client, baseURL, token, libID))

	t.Run("AC1_exact_parsed_values", func(t *testing.T) {
		qaAssertParsed(t, byRel)
		qaAssertFfprobeBlobs(t, byRel)
	})
	t.Run("AC6_corrupt_soft_fail", func(t *testing.T) {
		qaAssertCorruptSoftFail(t, byRel)
	})
	t.Run("AC4_escape_rejected", func(t *testing.T) {
		qaAssertEscapeRejected(t, byRel)
	})
	t.Run("AC1_rescan_idempotent", func(t *testing.T) {
		second := qaScanLibrary(t, client, baseURL, token, libID)
		if second.Persisted != first.Persisted {
			t.Fatalf("QA idempotency: re-scan persisted = %d, want %d (PutItem upsert by file_id)", second.Persisted, first.Persisted)
		}
		if got := len(qaListItems(t, client, baseURL, token, libID)); got != len(byRel) {
			t.Fatalf("QA idempotency: item count %d -> %d after re-scan (want unchanged)", len(byRel), got)
		}
	})
}

// qaExpected lists the base fields QA independently derives for each fixture
// after the Task 07 extraction: the library-relative path (echoed in parsed) +
// the extension. base-scanner is media-type-agnostic; the TV parse (title,
// season/episode, resolution, release_group) is produced by the tv-parser plugin
// (Task 06) and re-asserted at the full-pipeline level by the Task 11 golden.
var qaExpected = []qaExpectedItem{
	{rel: "Better Call Saul/Season 2/Better Call Saul S02E05.mkv", ext: ".mkv"},
	{rel: "Better Call Saul S02E06 720p-RG.mkv", ext: ".mkv"},
	{rel: "Чернобыль S01E03.mkv", ext: ".mkv"},
}

type qaExpectedItem struct {
	rel string
	ext string
}

func qaAssertParsed(t *testing.T, byRel map[string]qaItem) {
	t.Helper()
	for _, want := range qaExpected {
		it, ok := byRel[want.rel]
		if !ok {
			t.Errorf("QA AC-1: missing item for %q (have %v)", want.rel, qaPaths(byRel))
			continue
		}
		doc := qaParseDoc(t, it)
		if got := qaStr(doc.Parsed, "relative_path"); got != want.rel {
			t.Errorf("QA AC-1 %q: relative_path = %q, want %q", want.rel, got, want.rel)
		}
		if got := qaStr(doc.Parsed, "extension"); got != want.ext {
			t.Errorf("QA AC-1 %q: extension = %q, want %q", want.rel, got, want.ext)
		}
		// Structural/negative (AC-1 extraction): base-scanner emits no TV fields.
		for _, bad := range []string{"title", "season", "episode"} {
			if _, ok := doc.Parsed[bad]; ok {
				t.Errorf("QA AC-1 %q: parsed must not carry %q (TV parse extracted to tv-parser)", want.rel, bad)
			}
		}
		if doc.ModuleType != "tv" {
			t.Errorf("QA AC-1 %q: module_type = %q, want tv", want.rel, doc.ModuleType)
		}
	}
}

// qaAssertFfprobeBlobs proves the REAL ffprobe ran through the subprocess
// pipeline: the ffmpeg-generated media carry a non-empty, valid-JSON ffprobe.
func qaAssertFfprobeBlobs(t *testing.T, byRel map[string]qaItem) {
	t.Helper()
	for _, rel := range []string{
		"Better Call Saul/Season 2/Better Call Saul S02E05.mkv",
		"Better Call Saul S02E06 720p-RG.mkv",
		"Чернобыль S01E03.mkv",
	} {
		it, ok := byRel[rel]
		if !ok {
			t.Errorf("QA AC-1: %q not persisted; have %v", rel, qaPaths(byRel))
			continue
		}
		fp := qaParseDoc(t, it).Ffprobe
		if !json.Valid(fp) || len(fp) == 0 {
			t.Errorf("QA AC-1: %q ffprobe empty/invalid, want non-empty JSON (real ffprobe)", rel)
		}
	}
}

// qaAssertCorruptSoftFail proves AC-6: the zero-byte corrupt.mkv is STILL
// persisted (identified without ffprobe) with an EMPTY ffprobe field. One bad
// file never aborts the scan.
func qaAssertCorruptSoftFail(t *testing.T, byRel map[string]qaItem) {
	t.Helper()
	it, ok := byRel["corrupt.mkv"]
	if !ok {
		t.Fatalf("QA AC-6: corrupt.mkv not persisted (an unprobeable file must still be identified); have %v", qaPaths(byRel))
	}
	if fp := qaParseDoc(t, it).Ffprobe; len(fp) != 0 {
		t.Errorf("QA AC-6: corrupt.mkv ffprobe = %d bytes, want empty (soft-fail)", len(fp))
	}
}

// qaAssertEscapeRejected proves AC-4: an escaping symlink produces NO persisted
// item and nothing outside the root is probed. The escaping symlink here uses a
// RELATIVE ".." target (../qa-outside-secret.mkv) — a different vector than the
// coder's absolute /etc/passwd symlink.
//
// Grounding note (matches reviewer P2-2): filepath.WalkDir does not follow
// symlinks, so the escape is skipped silently — no warning surfaces. Asserting
// a warning here would be false to the implemented behavior. The real AC-4
// invariant — "no file outside the configured root is ffprobed/read/persisted"
// — is asserted: the escape yields no item, and the only persisted items are
// the in-root fixtures (verified by the discovered/persisted counts above).
func qaAssertEscapeRejected(t *testing.T, byRel map[string]qaItem) {
	t.Helper()
	if it, leaked := byRel["escape.mkv"]; leaked {
		t.Fatalf("QA AC-4: escaping escape.mkv was persisted (relative_path=%s) — outside-root access", it.RelativePath)
	}
}

// TestQA_Acceptance_ProtoVerbatim is the independent AC-3 spot-check (the coder
// has NO AC-3 test — this fills the gap). It asserts the load-bearing scanner
// proto is extracted VERBATIM from architecture.md §2.1.2: the §2.1.2 proto
// fence body equals scanner.proto body modulo the one go_package option line the
// generator requires. A renamed field/type/service anywhere diverges the two.
// It also pins the load-bearing invariants: bytes ffprobe_json (not Struct) and
// a streaming Scan RPC.
func TestQA_Acceptance_ProtoVerbatim(t *testing.T) {
	scannerProto := qaReadFile(t, filepath.Join("proto", "mellifera", "scanner", "v1", "scanner.proto"))
	archBody := qaProtoFenceBody(t, filepath.Join("docs", "architecture.md"), "#### 2.1.2 Scanner capability")

	archNorm := qaNormalizeProto(archBody)
	protoNorm := qaNormalizeProto(string(scannerProto))

	// arch §2.1.2 is verbatim-subset of the proto (the proto adds only the
	// go_package option the generator requires). Every arch declaration line
	// must appear verbatim in the proto.
	protoSet := make(map[string]struct{}, len(protoNorm))
	for _, l := range protoNorm {
		protoSet[l] = struct{}{}
	}
	for _, l := range archNorm {
		if _, ok := protoSet[l]; !ok {
			t.Errorf("QA AC-3: arch §2.1.2 line %q is NOT in scanner.proto (renamed/dropped field?)", l)
		}
	}

	// Load-bearing invariants pinned verbatim (B4/INV: bytes not Struct, streaming).
	for _, want := range []string{
		`bytes ffprobe_json = 5;`,
		`rpc Scan(ScanRequest) returns (stream DiscoveredFile);`,
		`rpc Identify(IdentifyRequest) returns (IdentifyResult);`,
		`service Scanner {`,
		`package mellifera.scanner.v1;`,
	} {
		if !strings.Contains(string(scannerProto), want) {
			t.Errorf("QA AC-3: scanner.proto missing verbatim declaration %q", want)
		}
	}
	// ffprobe_json MUST be bytes (not google.protobuf.Struct) — the foundational
	// dynamic-JSON decision. A Struct regression here fails loud.
	if strings.Contains(string(scannerProto), "google.protobuf.Struct ffprobe_json") {
		t.Error("QA AC-3: ffprobe_json regressed to google.protobuf.Struct; want bytes")
	}
}

// --- helpers (qa-prefixed to avoid collision with integration_test.go) ---

func qaBuildBinary(t *testing.T, tmp, name, pkg string) string {
	t.Helper()
	out := filepath.Join(tmp, name)
	build := exec.Command("go", "build", "-o", out, pkg)
	build.Dir = qaModuleRoot(t)
	if b, err := build.CombinedOutput(); err != nil {
		t.Fatalf("QA build %s: %v\n%s", pkg, err, b)
	}
	return out
}

func qaModuleRoot(t *testing.T) string {
	t.Helper()
	out, err := exec.Command("go", "list", "-m", "-f", "{{.Dir}}").Output()
	if err != nil {
		t.Fatalf("go list -m: %v", err)
	}
	return strings.TrimSpace(string(out))
}

// qaWriteFixtures builds the INDEPENDENT QA fixture tree. Three ffmpeg-generated
// real media files (TV parse incl Cyrillic + resolution/group strip), one
// zero-byte file (AC-6 soft-fail), one relative-.. escaping symlink (AC-4).
func qaWriteFixtures(t *testing.T) string {
	t.Helper()
	root := t.TempDir()

	nested := filepath.Join(root, "Better Call Saul", "Season 2")
	if err := os.MkdirAll(nested, 0o755); err != nil {
		t.Fatalf("mkdir: %v", err)
	}
	qaMakeMedia(t, filepath.Join(nested, "Better Call Saul S02E05.mkv"))
	qaMakeMedia(t, filepath.Join(root, "Better Call Saul S02E06 720p-RG.mkv"))
	qaMakeMedia(t, filepath.Join(root, "Чернобыль S01E03.mkv"))
	if err := os.WriteFile(filepath.Join(root, "corrupt.mkv"), nil, 0o644); err != nil {
		t.Fatalf("write corrupt.mkv: %v", err)
	}

	// AC-4: symlink with a RELATIVE ".." target escaping the root. The target
	// is a real file in a sibling dir so the symlink is resolvable (proves the
	// escape would be reachable if the guard were absent).
	sibling := t.TempDir()
	secret := filepath.Join(sibling, "qa-outside-secret.mkv")
	if err := os.WriteFile(secret, []byte("secret"), 0o644); err != nil {
		t.Fatalf("write outside secret: %v", err)
	}
	rel, err := filepath.Rel(root, secret)
	if err != nil {
		t.Fatalf("rel outside secret: %v", err)
	}
	if err := os.Symlink(rel, filepath.Join(root, "escape.mkv")); err != nil {
		t.Fatalf("symlink escape.mkv: %v", err)
	}
	return root
}

func qaMakeMedia(t *testing.T, path string) {
	t.Helper()
	if err := exec.Command("ffmpeg",
		"-f", "lavfi",
		"-i", "testsrc=duration=0.3:size=16x16:rate=10",
		"-loglevel", "error",
		"-y",
		filepath.Clean(path),
	).Run(); err != nil {
		t.Fatalf("ffmpeg generate %s: %v", filepath.Base(path), err)
	}
	if info, statErr := os.Stat(path); statErr != nil || info.Size() == 0 {
		t.Fatalf("QA media fixture %s not generated", filepath.Base(path))
	}
}

func qaStartServer(t *testing.T, serverBin, scannerBin, tvParserBin, tmp, token string) string {
	t.Helper()
	addr := net.JoinHostPort("127.0.0.1", qaFreePort(t))
	dataDir := filepath.Join(tmp, "qa-data")
	srv := exec.Command(serverBin)
	srv.Env = append(os.Environ(),
		"MELLIFERA_DATA_DIR="+dataDir,
		"MELLIFERA_ADMIN_TOKEN="+token,
		"MELLIFERA_BASE_SCANNER="+scannerBin,
		"MELLIFERA_TV_PARSER="+tvParserBin,
		"MELLIFERA_LISTEN="+addr,
	)
	var log strings.Builder
	srv.Stdout = &log
	srv.Stderr = &log
	if err := srv.Start(); err != nil {
		t.Fatalf("QA start server: %v", err)
	}
	baseURL := "http://" + addr
	t.Cleanup(func() {
		// Wait joins the process AND its stdout/stderr copier goroutines (which
		// write log) before the log dump — reading log.String() earlier races the
		// pipe copiers (a real data race under -race on the root integration tests).
		if srv.ProcessState == nil {
			_ = srv.Process.Signal(os.Interrupt)
		}
		done := make(chan struct{})
		go func() { _ = srv.Wait(); close(done) }()
		select {
		case <-done:
		case <-time.After(10 * time.Second):
			_ = srv.Process.Kill()
			<-done
		}
		t.Logf("QA server log:\n%s", log.String())
	})
	if !qaWaitReady(baseURL) {
		t.Fatalf("QA server not ready at %s; log:\n%s", baseURL, log.String())
	}
	return baseURL
}

func qaWaitReady(baseURL string) bool {
	probe := &http.Client{Timeout: time.Second}
	deadline := time.Now().Add(15 * time.Second)
	for time.Now().Before(deadline) {
		resp, err := probe.Get(baseURL + "/api/v1/items?library=0")
		if err == nil {
			resp.Body.Close()
			return true
		}
		time.Sleep(100 * time.Millisecond)
	}
	return false
}

func qaFreePort(t *testing.T) string {
	t.Helper()
	l, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		t.Fatalf("free port: %v", err)
	}
	defer l.Close()
	return fmt.Sprintf("%d", l.Addr().(*net.TCPAddr).Port)
}

func qaDo(t *testing.T, c *http.Client, method, url, token string, body, out any) int {
	t.Helper()
	var req *http.Request
	var err error
	if body != nil {
		buf, merr := json.Marshal(body)
		if merr != nil {
			t.Fatalf("marshal: %v", merr)
		}
		req, err = http.NewRequest(method, url, strings.NewReader(string(buf)))
	} else {
		req, err = http.NewRequest(method, url, nil)
	}
	if err != nil {
		t.Fatalf("new request %s %s: %v", method, url, err)
	}
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	if body != nil {
		req.Header.Set("Content-Type", "application/json")
	}
	resp, err := c.Do(req)
	if err != nil {
		t.Fatalf("do %s %s: %v", method, url, err)
	}
	defer resp.Body.Close()
	if out != nil {
		_ = json.NewDecoder(resp.Body).Decode(out)
	}
	return resp.StatusCode
}

