func qaIndexByPath(t *testing.T, items []qaItem) map[string]qaItem {
	t.Helper()
	out := make(map[string]qaItem, len(items))
	for _, it := range items {
		if _, dup := out[it.RelativePath]; dup {
			t.Fatalf("QA: duplicate item for relative path %q", it.RelativePath)
		}
		out[it.RelativePath] = it
	}
	return out
}

type qaDoc struct {
	ModuleType string          `json:"module_type"`
	Parsed     map[string]any  `json:"parsed"`
	Ffprobe    json.RawMessage `json:"ffprobe"`
}

func qaParseDoc(t *testing.T, it qaItem) qaDoc {
	t.Helper()
	var d qaDoc
	if err := json.Unmarshal(it.Document, &d); err != nil {
		t.Fatalf("QA unmarshal document for %q: %v (doc=%s)", it.RelativePath, err, it.Document)
	}
	return d
}

func qaStr(m map[string]any, k string) string { s, _ := m[k].(string); return s }

func qaNum(m map[string]any, k string) int64 {
	f, ok := m[k].(float64)
	if !ok {
		return -1
	}
	return int64(f)
}

func qaPaths(m map[string]qaItem) []string {
	out := make([]string, 0, len(m))
	for k := range m {
		out = append(out, k)
	}
	return out
}

func qaWarnsAbout(warnings []string, sub string) bool {
	for _, w := range warnings {
		if strings.Contains(w, sub) {
			return true
		}
	}
	return false
}

// qaProtoFenceBody reads mdPath, finds the section starting with headerPrefix,
// and returns the text inside the first ```proto ... ``` fence in that section.
func qaProtoFenceBody(t *testing.T, mdPath, headerPrefix string) string {
	t.Helper()
	md := string(qaReadFile(t, mdPath))
	rest := md
	idx := strings.Index(rest, headerPrefix)
	if idx < 0 {
		t.Fatalf("QA AC-3: %s section %q not found", mdPath, headerPrefix)
	}
	rest = rest[idx:]
	open := strings.Index(rest, "```proto")
	if open < 0 {
		t.Fatalf("QA AC-3: no ```proto fence under %q", headerPrefix)
	}
	rest = rest[open+len("```proto"):]
	close := strings.Index(rest, "```")
	if close < 0 {
		t.Fatalf("QA AC-3: unterminated proto fence under %q", headerPrefix)
	}
	return rest[:close]
}

// qaNormalizeProto returns the significant proto lines: trimmed, blanks dropped,
// and the go_package option removed (the generator-required line arch §2 omits).
func qaNormalizeProto(body string) []string {
	var out []string
	for _, raw := range strings.Split(body, "\n") {
		l := strings.TrimSpace(raw)
		if l == "" || strings.HasPrefix(l, "//") {
			continue
		}
		if strings.HasPrefix(l, "option go_package") {
			continue
		}
		out = append(out, l)
	}
	return out
}

func qaReadFile(t *testing.T, rel string) []byte {
	t.Helper()
	root := qaModuleRoot(t)
	b, err := os.ReadFile(filepath.Join(root, rel))
	if err != nil {
		t.Fatalf("QA read %s: %v", rel, err)
	}
	return b
}
